import os
import importlib
import logging

logger = logging.getLogger(__name__)


def _discover_ops_from_entry_points():
    ops = {}
    try:
        from importlib.metadata import entry_points

        eps = entry_points(group="cann_ops_nn.ops")
        for ep in eps:
