304	static inline void TryLoadCustOpApiFromEnv(const char* env_name, const std::string& sub_dir,
305	                                           std::vector<void*>& handlers, std::set<std::string>& loaded_paths)
306	{
307	    const char* env = std::getenv(env_name);
308	    if (env == nullptr) {
309	        return;
310	    }
311	    std::istringstream stream(env);
312	    std::string dir;
313	    while (std::getline(stream, dir, ':')) {
314	        if (dir.empty()) {
315	            continue;
316	        }
317	        std::string so_path_str = dir + sub_dir + GetCustOpApiLibName();
318	        char so_path[PATH_MAX] = {0};
319	        if (realpath(so_path_str.c_str(), so_path) == nullptr) {
320	            int errno_copy = errno;
321	            ASCEND_LOGW("realpath failed for %s, errno=%d(%s).", so_path_str.c_str(), errno_copy, strerror(errno_copy));
322	            continue;
323	        }
324	        if (!loaded_paths.insert(so_path).second) {
325	            continue;
326	        }
327	        auto handler = dlopen(so_path, RTLD_LAZY);
328	        if (handler != nullptr) {
329	            handlers.push_back(handler);
330	        } else {
331	            ASCEND_LOGW("dlopen %s failed, error:%s.", so_path, dlerror());
332	        }
333	    }
334	}
