391	    } else if (acl_input->scalar_type() == at::ScalarType::Bool) {
392	        int8_t value = *(int8_t*)acl_input->data_ptr();
393	        return c10::Scalar(value);
394	    } else if (acl_input->scalar_type() == at::ScalarType::ComplexDouble) {
