428	TensorMeta PrepareTensorMeta(const at::Tensor& at_tensor, aclDataType acl_data_type)
429	{
430	    TensorMeta meta;
431	    meta.wrapperStride = op_infer::array_to_small_vector(at_tensor.strides());
432	    meta.wrapperShape = op_infer::array_to_small_vector(at_tensor.sizes());
433	
434	    const auto dimNum = at_tensor.sizes().size();
435	    meta.format = ACL_FORMAT_ND;
436	    const bool isBaseFormat = IsOpInputBaseFormat(at_tensor);
437	    if (!isBaseFormat) {
438	        meta.format = static_cast<aclFormat>(at_npu::native::get_npu_format(at_tensor));
439	        if (acl_data_type != ACL_STRING) {
440	            TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
441	            meta.storageDims = at_npu::native::get_npu_storage_sizes(at_tensor);
442	        }
443	    } else {
444	        switch (dimNum) {
445	            case 3:
446	                meta.format = ACL_FORMAT_NCL;
447	                break;
448	            case 4:
449	                meta.format = ACL_FORMAT_NCHW;
450	                break;
451	            case 5:
452	                meta.format = ACL_FORMAT_NCDHW;
453	                break;
454	            default:
455	                meta.format = ACL_FORMAT_ND;
456	        }
457	        if (acl_data_type != ACL_STRING) {
458	            TORCH_CHECK(at_tensor.itemsize() > 0, "the itemsize of tensor must be greater than 0.");
459	            meta.storageDims.push_back(at_tensor.storage().nbytes() / at_tensor.itemsize());
460	        }
461	    }
462	
463	    if (acl_data_type != ACL_STRING && Is4BitDtype(acl_data_type)) {
464	        CollectB4ShapeInfo(at_tensor, meta.wrapperStride, meta.wrapperShape);
465	        meta.storageDims.back() *= FP4_IN_INT8;
466	        if (!isBaseFormat) {
467	            auto realFormat = FORMAT_FAKE_TO_REAL.find(meta.format);
468	            TORCH_CHECK(realFormat != FORMAT_FAKE_TO_REAL.end(), "not support convert format ", meta.format, ".");
469	            meta.format = realFormat->second;
470	        }
471	    }
472	
473	    return meta;
474	}
