476	inline aclTensor* ConvertType(const at::Tensor& at_tensor)
477	{
478	    static const auto aclCreateTensor = GET_OP_API_FUNC(CreateTensor);
479	    if (aclCreateTensor == nullptr) {
480	        return nullptr;
481	    }
482	
483	    if (!at_tensor.defined()) {
484	        return nullptr;
485	    }
486	
487	    at::ScalarType scalar_data_type = at_tensor.scalar_type();
488	    aclDataType acl_data_type = ConvertToAclDataType(scalar_data_type);
489	    auto meta = PrepareTensorMeta(at_tensor, acl_data_type);
490	
491	    if (at_tensor.unsafeGetTensorImpl()->is_wrapped_number()) {
492	        c10::Scalar exp_scalar = ConvertTensorToScalar(at_tensor);
493	        at::Tensor acl_input = CopyScalarToDevice(exp_scalar, scalar_data_type);
494	        return aclCreateTensor(acl_input.sizes().data(), acl_input.sizes().size(), acl_data_type,
495	                               acl_input.strides().data(), acl_input.storage_offset(), meta.format,
496	                               meta.storageDims.data(), meta.storageDims.size(),
497	                               const_cast<void*>(acl_input.storage().data()));
498	    }
499	
500	    auto acl_tensor = aclCreateTensor(meta.wrapperShape.data(), at_tensor.sizes().size(), acl_data_type,
501	                                      meta.wrapperStride.data(), ConvertToAclStorageOffset(at_tensor, acl_data_type),
502	                                      meta.format, meta.storageDims.data(), meta.storageDims.size(),
503	                                      const_cast<void*>(at_tensor.storage().data()));
504	    return acl_tensor;
505	}
