531	            return aclCreateScalar(&value, acl_data_type);
532	        }
533	        case at::ScalarType::Int: {
534	            int value = at_scalar.toInt();
535	            return aclCreateScalar(&value, acl_data_type);
536	        }
537	        case at::ScalarType::Half: {
538	            c10::Half value = at_scalar.toHalf();
539	            return aclCreateScalar(&value, acl_data_type);
540	        }
541	        case at::ScalarType::BFloat16: {
542	            c10::BFloat16 value = at_scalar.toBFloat16();
543	            return aclCreateScalar(&value, acl_data_type);
544	        }
