954	 * 查找第一个 at::Tensor
955	 */
956	template <std::size_t I = 0, typename... Ts>
957	typename std::enable_if<I == sizeof...(Ts), bool>::type GetFirstTensor(const std::tuple<Ts...>& t, at::Tensor& res)
958	{
959	    return false;
960	}
961	
962	template <std::size_t I = 0, typename... Ts>
963	    typename std::enable_if < I<sizeof...(Ts), bool>::type GetFirstTensor(const std::tuple<Ts...>& t, at::Tensor& res)
964	{
965	    if constexpr (is_at_tensor<typename std::tuple_element<I, std::tuple<Ts...>>::type>::value) {
966	        res = std::get<I>(t);
967	        return true;
968	    } else if constexpr (is_at_tensor_list<typename std::tuple_element<I, std::tuple<Ts...>>::type>::value) {
969	        const auto& tl = std::get<I>(t);
970	        if (tl.size() == 0) {
971	            return GetFirstTensor<I + 1, Ts...>(t, res);
972	        }
973	        res = tl[0];
974	        return true;
975	    } else if constexpr (is_tensor_wrapper<typename std::tuple_element<I, std::tuple<Ts...>>::type>::value) {
976	        res = std::get<I>(t).tensor;
977	        return true;
978	    } else if constexpr (is_tensor_list_wrapper<typename std::tuple_element<I, std::tuple<Ts...>>::type>::value) {
979	        const auto& tl = std::get<I>(t).tensor_list;
980	        if (tl.size() == 0) {
981	            return GetFirstTensor<I + 1, Ts...>(t, res);
982	        }
983	        res = tl[0];
984	        return true;
985	    }
986	    return GetFirstTensor<I + 1, Ts...>(t, res);
987	}
